  /* NIH-style hero banner with blue/teal gradient */
  .hero-banner {
    background: linear-gradient(135deg, #09375e 0%, #13778a 100%);
    color: white;
    padding: 40px 30px;
    margin-top: -20px; /* pull flush against the navbar */
